80: function tierWeight(tier,pack){
81:   let weights={Normal:56,Gold:19,Rare:12,Diamond:7,Godlike:3.3,Special:2,Secret:.7};
82:   if(pack==='moon'){weights={Normal:47,Gold:20,Rare:15,Diamond:9,Godlike:4.5,Special:3,Secret:1.5};}
83:   if(pack==='solar'){weights={Normal:39,Gold:21,Rare:17,Diamond:12,Godlike:6,Special:3.5,Secret:1.5};}
84:   let luck=1+state.rebirths*.25;
85:   if(tier==='Normal')return weights[tier]/luck;
86:   return weights[tier]*luck;
87: }
88: function drawCard(packId){
89:   if(state.huntTarget&&Math.random()<Math.min(.3,.15+state.rebirths*.02)){
90:     const target=CARD_POOL.find(c=>c.id===state.huntTarget);if(target)return target;
91:   }
92:   const pack=PACKS.find(p=>p.id===packId)||PACKS[0];
93:   let pool=CARD_POOL.filter(c=>c.pack===packId);
94:   if(pool.length<3)pool=CARD_POOL;
95:   const weighted=pool.map(c=>({card:c,weight:tierWeight(c.tier,packId)}));
96:   const total=weighted.reduce((a,x)=>a+x.weight,0);let n=Math.random()*total;
97:   for(const entry of weighted){n-=entry.weight;if(n<=0)return entry.card;}
98:   return weighted[0].card;
99: }
